curl -s -X POST https://slack.com/api/users.conversations -H "Authorization: Bearer <TOKEN>" -d "user=U_VICTOR&types=public_channel,private_channel&limit=999" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data['ok']:
    for ch in data['channels']:
        print(f\"ID: {ch['id']}, Name: {ch['name']}, Created: {ch.get('created', 'N/A')}, is_private: {ch.get('is_private', False)}, is_archived: {ch.get('is_archived', False)}\")
else:
    print(json.dumps(data, indent=2))
"

